"""Data model and calculations for the kitty.

All money is handled as Decimal and rounded to cents. Every expense and
payment stores its value in the main currency ("base_amount") at the moment
it is recorded, so changing an exchange rate later never rewrites history.
"""

import datetime
import json
import os
import re
import tempfile
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation

DATA_FILE = "kitty.json"
FORMAT_VERSION = 1
CENT = Decimal("0.01")
MAX_AMOUNT = Decimal("1000000000000")  # sanity cap for amounts
MAX_RATE = Decimal("1000000000")
DEFAULT_CATEGORY = "other"

_CURRENCY_RE = re.compile(r"^[A-Z]{3}$")
_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


class KittyError(Exception):
    """A problem caused by user input or the data file; shown as a message."""


# ---------------------------------------------------------------- parsing ---

def to_cents(value):
    return value.quantize(CENT, rounding=ROUND_HALF_UP)


def fmt(value):
    """Format money as text with two decimals, e.g. '41.40' or '-20.70'."""
    value = to_cents(value)
    if value == 0:
        value = abs(value)  # never print "-0.00"
    return "{:.2f}".format(value)


def _parse_decimal(text, what):
    text = text.strip()
    try:
        value = Decimal(text)
    except InvalidOperation:
        hint = ""
        if "," in text:
            hint = " (use a dot for decimals, e.g. 12.50)"
        raise KittyError("{} '{}' is not a number{}".format(what, text, hint))
    if not value.is_finite():
        raise KittyError("{} '{}' is not a number".format(what, text))
    return value


def parse_amount(text, what="amount"):
    """A positive amount of money with at most two decimals."""
    value = _parse_decimal(text, what)
    if value <= 0:
        raise KittyError("{} must be greater than zero, got '{}'".format(what, text))
    if value >= MAX_AMOUNT:
        raise KittyError("{} '{}' is too large".format(what, text))
    if value != to_cents(value):
        raise KittyError("{} '{}' has more than two decimals".format(what, text))
    return value


def parse_rate(text):
    value = _parse_decimal(text, "rate")
    if value <= 0:
        raise KittyError("rate must be greater than zero, got '{}'".format(text))
    if value >= MAX_RATE:
        raise KittyError("rate '{}' is too large".format(text))
    return value


def parse_currency(text):
    code = text.strip().upper()
    if not _CURRENCY_RE.match(code):
        raise KittyError(
            "currency '{}' should be a three-letter code like EUR or USD".format(text))
    return code


def parse_date(text):
    text = text.strip()
    try:
        if not _DATE_RE.match(text):
            raise ValueError
        datetime.datetime.strptime(text, "%Y-%m-%d")
    except ValueError:
        raise KittyError(
            "date '{}' is not a valid date; use YYYY-MM-DD, e.g. 2026-07-14".format(text))
    return text


def today():
    return datetime.date.today().isoformat()


def parse_pairs(text, option):
    """Parse 'A=30,B=20' into [('A', '30'), ('B', '20')]."""
    pairs = []
    for item in text.split(","):
        item = item.strip()
        if not item:
            continue
        if "=" not in item:
            raise KittyError(
                "{}: '{}' should look like NAME=NUMBER".format(option, item))
        name, _, value = item.partition("=")
        pairs.append((name.strip(), value.strip()))
    if not pairs:
        raise KittyError("{}: no people given".format(option))
    return pairs


def allocate(total, weights):
    """Split `total` (a cent amount) in proportion to `weights`.

    Uses the largest-remainder method so the parts always add up exactly to
    the total; leftover cents go to the largest remainders, ties going to
    whoever comes first.
    """
    total_cents = int(to_cents(total) / CENT)
    weight_sum = sum(weights)
    raw = [Decimal(total_cents) * w / weight_sum for w in weights]
    floors = [int(r) for r in raw]  # all values are >= 0, so int() floors
    leftover = total_cents - sum(floors)
    order = sorted(range(len(weights)), key=lambda i: (-(raw[i] - floors[i]), i))
    for i in order[:leftover]:
        floors[i] += 1
    return [Decimal(c) * CENT for c in floors]


# ------------------------------------------------------------------ kitty ---

class Kitty:
    def __init__(self, currency):
        self.currency = currency
        self.members = []
        self.rates = {}
        self.expenses = []
        self.payments = []
        self.next_expense_id = 1
        self.next_seq = 1  # common counter to keep entry order across types

    # -------------------------------------------------------- storage ---

    @classmethod
    def load(cls, path=DATA_FILE):
        if not os.path.exists(path):
            raise KittyError(
                "no kitty here yet ({} not found); start one with: init EUR".format(path))
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
            kitty = cls(data["currency"])
            kitty.members = list(data["members"])
            kitty.rates = {k: Decimal(v) for k, v in data["rates"].items()}
            kitty.next_expense_id = int(data["next_expense_id"])
            kitty.next_seq = int(data["next_seq"])
            for e in data["expenses"]:
                kitty.expenses.append({
                    "id": int(e["id"]),
                    "seq": int(e["seq"]),
                    "date": str(e["date"]),
                    "payer": str(e["payer"]),
                    "description": str(e["description"]),
                    "amount": Decimal(e["amount"]),
                    "currency": str(e["currency"]),
                    "base_amount": Decimal(e["base_amount"]),
                    "category": str(e["category"]),
                    "shares": {str(k): Decimal(v) for k, v in e["shares"].items()},
                })
            for p in data["payments"]:
                kitty.payments.append({
                    "seq": int(p["seq"]),
                    "date": str(p["date"]),
                    "from": str(p["from"]),
                    "to": str(p["to"]),
                    "amount": Decimal(p["amount"]),
                    "currency": str(p["currency"]),
                    "base_amount": Decimal(p["base_amount"]),
                })
        except (OSError, ValueError, KeyError, TypeError, AttributeError,
                InvalidOperation) as exc:
            raise KittyError("{} could not be read, it may be damaged ({})".format(
                path, exc.__class__.__name__))
        return kitty

    def to_dict(self):
        return {
            "version": FORMAT_VERSION,
            "currency": self.currency,
            "members": self.members,
            "rates": {k: str(v) for k, v in sorted(self.rates.items())},
            "next_expense_id": self.next_expense_id,
            "next_seq": self.next_seq,
            "expenses": [
                dict(e, amount=fmt(e["amount"]), base_amount=fmt(e["base_amount"]),
                     shares={k: fmt(v) for k, v in e["shares"].items()})
                for e in self.expenses
            ],
            "payments": [
                dict(p, amount=fmt(p["amount"]), base_amount=fmt(p["base_amount"]))
                for p in self.payments
            ],
        }

    def save(self, path=DATA_FILE):
        # Write to a temporary file first so a crash can't leave a half-written file.
        directory = os.path.dirname(os.path.abspath(path))
        fd, tmp = tempfile.mkstemp(dir=directory, prefix=".kitty-", suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(self.to_dict(), f, indent=2, ensure_ascii=False)
                f.write("\n")
            os.replace(tmp, path)
        except BaseException:
            if os.path.exists(tmp):
                os.unlink(tmp)
            raise

    def _take_seq(self):
        seq = self.next_seq
        self.next_seq += 1
        return seq

    # -------------------------------------------------------- members ---

    def find_member(self, name):
        """Return the member's name as stored; matching ignores upper/lower case."""
        wanted = name.strip().casefold()
        for m in self.members:
            if m.casefold() == wanted:
                return m
        if not self.members:
            raise KittyError("'{}' is not in the group (the group is empty; "
                             "add people with: member add NAME)".format(name))
        raise KittyError("'{}' is not in the group (members: {})".format(
            name, ", ".join(self.members)))

    def add_member(self, name):
        name = name.strip()
        if not name:
            raise KittyError("name cannot be empty")
        if any(c in name for c in ",="):
            raise KittyError("name '{}' cannot contain ',' or '='".format(name))
        if name.startswith("-"):
            raise KittyError("name '{}' cannot start with '-'".format(name))
        for m in self.members:
            if m.casefold() == name.casefold():
                raise KittyError("'{}' is already in the group".format(m))
        self.members.append(name)

    def remove_member(self, name):
        name = self.find_member(name)
        used = [e["id"] for e in self.expenses
                if e["payer"] == name or name in e["shares"]]
        if used:
            raise KittyError(
                "can't remove {}: they are part of expense(s) {}; remove those "
                "first".format(name, ", ".join(str(i) for i in used)))
        if any(name in (p["from"], p["to"]) for p in self.payments):
            raise KittyError(
                "can't remove {}: they are part of a recorded payment".format(name))
        self.members.remove(name)

    # ---------------------------------------------------------- rates ---

    def set_rate(self, currency, rate):
        currency = parse_currency(currency)
        if currency == self.currency:
            raise KittyError("{} is the main currency; its rate is always 1".format(
                currency))
        self.rates[currency] = parse_rate(rate)

    def to_base(self, amount, currency):
        if currency == self.currency:
            return amount
        if currency not in self.rates:
            raise KittyError(
                "no exchange rate for {}; set one first with: rate set {} RATE "
                "(how much 1 {} is worth in {})".format(
                    currency, currency, currency, self.currency))
        return to_cents(amount * self.rates[currency])

    # ------------------------------------------------------- expenses ---

    def add_expense(self, payer, amount, description, among=None, exact=None,
                    shares=None, percent=None, currency=None, date=None,
                    category=None):
        payer = self.find_member(payer)
        amount = parse_amount(amount)
        description = description.strip()
        if not description:
            raise KittyError("description cannot be empty")
        currency = parse_currency(currency) if currency else self.currency
        date = parse_date(date) if date else today()
        category = category.strip().lower() if category is not None else DEFAULT_CATEGORY
        if not category:
            raise KittyError("category cannot be empty")

        chosen = [x for x in (among, exact, shares, percent) if x is not None]
        if len(chosen) > 1:
            raise KittyError("use only one of --among, --exact, --shares, --percent")

        base_amount = self.to_base(amount, currency)
        if base_amount <= 0:
            raise KittyError("{} {} is less than 0.01 {} after conversion".format(
                fmt(amount), currency, self.currency))

        if exact is not None:
            people, values = self._weighted(exact, "--exact", parse_amount)
            if sum(values) != amount:
                raise KittyError("--exact amounts add up to {} but the expense is {}".format(
                    fmt(sum(values)), fmt(amount)))
            weights = values
        elif shares is not None:
            people, weights = self._weighted(shares, "--shares", self._parse_weight)
        elif percent is not None:
            people, weights = self._weighted(percent, "--percent", self._parse_weight)
            if sum(weights) != 100:
                raise KittyError("--percent values add up to {} instead of 100".format(
                    sum(weights).normalize()))
        else:
            if among is not None:
                people = self._names_list(among, "--among")
            else:
                people = list(self.members)
            weights = [Decimal(1)] * len(people)
        if not people:
            raise KittyError("there is nobody to split this expense between")

        parts = allocate(base_amount, weights)
        # Keep shares in group order so output is predictable.
        split = dict(zip(people, parts))
        ordered = {m: split[m] for m in self.members if m in split}

        expense = {
            "id": self.next_expense_id,
            "seq": self._take_seq(),
            "date": date,
            "payer": payer,
            "description": description,
            "amount": amount,
            "currency": currency,
            "base_amount": base_amount,
            "category": category,
            "shares": ordered,
        }
        self.next_expense_id += 1
        self.expenses.append(expense)
        return expense

    @staticmethod
    def _parse_weight(text, what):
        value = _parse_decimal(text, what)
        if value <= 0:
            raise KittyError("{} must be greater than zero, got '{}'".format(what, text))
        if value >= MAX_AMOUNT:
            raise KittyError("{} '{}' is too large".format(what, text))
        return value

    def _names_list(self, text, option):
        people = []
        for raw in text.split(","):
            if not raw.strip():
                continue
            name = self.find_member(raw)
            if name in people:
                raise KittyError("{}: {} is listed twice".format(option, name))
            people.append(name)
        if not people:
            raise KittyError("{}: no people given".format(option))
        return people

    def _weighted(self, text, option, parse_value):
        people, values = [], []
        for raw_name, raw_value in parse_pairs(text, option):
            name = self.find_member(raw_name)
            if name in people:
                raise KittyError("{}: {} is listed twice".format(option, name))
            people.append(name)
            values.append(parse_value(raw_value, "{} value for {}".format(option, name)))
        return people, values

    def remove_expense(self, expense_id):
        try:
            wanted = int(expense_id)
        except ValueError:
            raise KittyError("expense ID '{}' is not a number".format(expense_id))
        for e in self.expenses:
            if e["id"] == wanted:
                self.expenses.remove(e)
                return e
        raise KittyError("there is no expense with ID {}".format(wanted))

    # ------------------------------------------------------- payments ---

    def add_payment(self, sender, receiver, amount, currency=None, date=None):
        sender = self.find_member(sender)
        receiver = self.find_member(receiver)
        if sender == receiver:
            raise KittyError("a payment needs two different people")
        amount = parse_amount(amount)
        currency = parse_currency(currency) if currency else self.currency
        date = parse_date(date) if date else today()
        base_amount = self.to_base(amount, currency)
        if base_amount <= 0:
            raise KittyError("{} {} is less than 0.01 {} after conversion".format(
                fmt(amount), currency, self.currency))
        payment = {
            "seq": self._take_seq(),
            "date": date,
            "from": sender,
            "to": receiver,
            "amount": amount,
            "currency": currency,
            "base_amount": base_amount,
        }
        self.payments.append(payment)
        return payment

    # -------------------------------------------------------- reports ---

    def events(self):
        """Every expense and payment as (date, seq, description, {name: change})."""
        out = []
        for e in self.expenses:
            changes = {}
            changes[e["payer"]] = e["base_amount"]
            for name, share in e["shares"].items():
                changes[name] = changes.get(name, Decimal(0)) - share
            out.append((e["date"], e["seq"], e["description"], changes))
        for p in self.payments:
            desc = "Payment from {} to {}".format(p["from"], p["to"])
            changes = {p["from"]: p["base_amount"], p["to"]: -p["base_amount"]}
            out.append((p["date"], p["seq"], desc, changes))
        out.sort(key=lambda ev: (ev[0], ev[1]))
        return out

    def balances(self):
        totals = {m: Decimal(0) for m in self.members}
        for _, _, _, changes in self.events():
            for name, change in changes.items():
                totals[name] = totals.get(name, Decimal(0)) + change
        return totals

    def settle(self):
        """Suggest transfers: the biggest debtor pays the biggest creditor, repeatedly."""
        order = {m: i for i, m in enumerate(self.members)}
        bal = {m: to_cents(v) for m, v in self.balances().items()}
        creditors = [[m, v] for m, v in bal.items() if v > 0]
        debtors = [[m, -v] for m, v in bal.items() if v < 0]
        transfers = []
        while creditors and debtors:
            creditors.sort(key=lambda x: (-x[1], order.get(x[0], 0)))
            debtors.sort(key=lambda x: (-x[1], order.get(x[0], 0)))
            cred, debt = creditors[0], debtors[0]
            amount = min(cred[1], debt[1])
            transfers.append({"from": debt[0], "to": cred[0], "amount": amount})
            cred[1] -= amount
            debt[1] -= amount
            if cred[1] == 0:
                creditors.pop(0)
            if debt[1] == 0:
                debtors.pop(0)
        return transfers

    def history(self, name):
        name = self.find_member(name)
        running = Decimal(0)
        rows = []
        for date, _, description, changes in self.events():
            if name not in changes:
                continue
            running += changes[name]
            rows.append({"date": date, "description": description,
                         "change": changes[name], "balance": running})
        return rows

    def report(self):
        """Per category, how much each person's share of the expenses came to."""
        result = {}
        for e in self.expenses:
            cat = result.setdefault(e["category"], {})
            for name, share in e["shares"].items():
                cat[name] = cat.get(name, Decimal(0)) + share
        order = {m: i for i, m in enumerate(self.members)}
        return {
            category: dict(sorted(people.items(), key=lambda kv: order.get(kv[0], 0)))
            for category, people in sorted(result.items())
        }

