    # -------------------------------------------------------- reports ---

    def events(self):
        """Every expense and payment as (date, seq, description, {name: change})."""
        out = []
        for e in self.expenses:
            changes = {}
            changes[e["payer"]] = e["base_amount"]
            for name, share in e["shares"].items():
                changes[name] = changes.get(name, Decimal(0)) - share
            out.append((e["date"], e["seq"], e["description"], changes))
        for p in self.payments:
            desc = "Payment from {} to {}".format(p["from"], p["to"])
            changes = {p["from"]: p["base_amount"], p["to"]: -p["base_amount"]}
            out.append((p["date"], p["seq"], desc, changes))
        out.sort(key=lambda ev: (ev[0], ev[1]))
        return out

    def balances(self):
        totals = {m: Decimal(0) for m in self.members}
        for _, _, _, changes in self.events():
            for name, change in changes.items():
                totals[name] = totals.get(name, Decimal(0)) + change
        return totals

    def settle(self):
        """Suggest transfers: the biggest debtor pays the biggest creditor, repeatedly."""
        order = {m: i for i, m in enumerate(self.members)}
        bal = {m: to_cents(v) for m, v in self.balances().items()}
        creditors = [[m, v] for m, v in bal.items() if v > 0]
        debtors = [[m, -v] for m, v in bal.items() if v < 0]
        transfers = []
        while creditors and debtors:
            creditors.sort(key=lambda x: (-x[1], order.get(x[0], 0)))
            debtors.sort(key=lambda x: (-x[1], order.get(x[0], 0)))
            cred, debt = creditors[0], debtors[0]
            amount = min(cred[1], debt[1])
            transfers.append({"from": debt[0], "to": cred[0], "amount": amount})
            cred[1] -= amount
            debt[1] -= amount
            if cred[1] == 0:
                creditors.pop(0)
            if debt[1] == 0:
                debtors.pop(0)
        return transfers

    def history(self, name):
        name = self.find_member(name)
        running = Decimal(0)
        rows = []
        for date, _, description, changes in self.events():
            if name not in changes:
                continue
            running += changes[name]
            rows.append({"date": date, "description": description,
                         "change": changes[name], "balance": running})
        return rows

    def report(self):
        """Per category, how much each person's share of the expenses came to."""
        result = {}
        for e in self.expenses:
            cat = result.setdefault(e["category"], {})
            for name, share in e["shares"].items():
                cat[name] = cat.get(name, Decimal(0)) + share
        order = {m: i for i, m in enumerate(self.members)}
        return {
            category: dict(sorted(people.items(), key=lambda kv: order.get(kv[0], 0)))
            for category, people in sorted(result.items())
        }
